INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('rev-1', 'Executive Director 1', 'المدير التنفيذي 1', 'Al-Jazeera Gulf Holdings W.L.L.', 'مجموعة الجزيرة الخليجية القابضة', 'Working with Lumina Atelier streamlined our operations and exceeded delivery expectations.', 'العمل مع لومينا أتيليه ساهم في رفع كفاءة عملياتنا وتجاوز توقعاتنا في التسليم.', 5, true, 1, 2026, now() - interval '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'lumina-atelier-insights-1', 'Lumina Atelier Industry Brief #1: Botanical Hydration Facial (75 min)', 'تقرير لومينا أتيليه التخصصي #1: جلسة ترطيب نباتي للوجه (75 دقيقة)', 'Key operational benchmarks and best practices from Lumina Atelier in Riffa.', 'أبرز المعايير التشغيلية وأفضل الممارسات من لومينا أتيليه في Riffa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary. Our Botanical Hydration Facial (75 min) division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية. يساعد قسم جلسة ترطيب نباتي للوجه (75 دقيقة) المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.</p><p>Our Botanical Hydration Facial (75 min) division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.</p><p>يساعد قسم جلسة ترطيب نباتي للوجه (75 دقيقة) المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'beauty', '{"beauty","Riffa","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '9 days', true, now() - interval '9 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How do we engage Lumina Atelier for a new project?', 'كيف يمكننا البدء بمشروع جديد مع لومينا أتيليه؟', 'Contact Lumina Atelier at concierge@luminaatelier.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر concierge@luminaatelier.bh أو إرسال طلب إلكتروني وسيرد فريق لومينا أتيليه خلال يوم عمل واحد.', 'general', true, 1, now()) ON CONFLICT (id) DO NOTHING;
